# Helper to determine if any records show abnormal vitals
def records_have_abnormal(records):
    # For testing, suppose records are list of dicts with 'abnormal':True/False
    return any(r.get('abnormal', False) for r in records)

def patient_risk_score(hospital, patient_id):
    '''
    See prompt for specification.
    '''
    patient = hospital.get_patient(patient_id)
    age_score = patient.age / 100 * 30
    conditions_score = patient.get_total_conditions() * 5 * 0.25
    severity_score = patient.get_average_severity() * 10 * 0.25
    recent_records = hospital.get_recent_records(patient_id, 90)
    abnormal_score = 20 if records_have_abnormal(recent_records) else 0
    total = age_score + conditions_score + severity_score + abnormal_score
    return max(0.0, min(100.0, float(total)))  # Clamp between 0.0 and 100.0

