# Assuming the existence of `Hospital` and `Patient` classes with the described interfaces.
# Mock implementations for testing.

class MockPatient:
    def __init__(self, age, conditions, severities):
        self.age = age
        self._conditions = conditions  # list of condition names
        self._severities = severities  # list of severity scores (float)

    def get_total_conditions(self):
        return len(self._conditions)

    def get_average_severity(self):
        if not self._severities:
            return 0.0
        return sum(self._severities) / len(self._severities)

class MockHospital:
    def __init__(self, patients, records):
        # patients: {patient_id: MockPatient}
        # records: {patient_id: [record dict]}
        self.patients = patients
        self.records = records

    def get_patient(self, patient_id):
        return self.patients[patient_id]

    def get_recent_records(self, patient_id, days):
        # Assume all records in self.records[patient_id] are "recent"
        return self.records.get(patient_id, [])

def is_abnormal_vitals(record):
    # Helper: suppose vitals are keys in record dict, any abnormal means True
    # For test, means record['abnormal'] == True
    return record.get('abnormal', False)

def patient_risk_score(hospital, patient_id):
    '''
    Create a function called patient_risk_score that takes a Hospital object and patient_id.
    Calculate risk score using formula:
        (patient.age / 100 * 30)
        + (patient.get_total_conditions() * 5 * 25/100)
        + (patient.get_average_severity() * 10 * 25/100)
        + (20 if recent records have abnormal vitals else 0).
    Use hospital.get_patient(patient_id) and hospital.get_recent_records(patient_id, 90).
    Returns: float between 0.0 and 100.0.
    '''
    patient = hospital.get_patient(patient_id)
    age_score = (patient.age / 100) * 30
    condition_score = patient.get_total_conditions() * 5 * 0.25
    severity_score = patient.get_average_severity() * 10 * 0.25
    records = hospital.get_recent_records(patient_id, 90)
    abnormal = any(is_abnormal_vitals(r) for r in records)
    abnormal_score = 20 if abnormal else 0
    total = age_score + condition_score + severity_score + abnormal_score
    # Clamp between 0 and 100
    return min(max(total, 0.0), 100.0)

