# Assuming existence of Hospital and Patient classes with the required API.
# We'll use mocks for testing.

class MockPatient:
    def __init__(self, age, cond_count, severity):
        self.age = age
        self._cond_count = cond_count
        self._severity = severity

    def get_total_conditions(self):
        return self._cond_count

    def get_average_severity(self):
        return self._severity

class MockHospital:
    def __init__(self, patients, records):
        # patients: dict patient_id -> MockPatient
        # records: dict patient_id -> list of vital dicts: {'abnormal': True/False}
        self.patients = patients
        self.records = records

    def get_patient(self, patient_id):
        return self.patients[patient_id]

    def get_recent_records(self, patient_id, days):
        return self.records.get(patient_id, [])

def patient_risk_score(hospital, patient_id):
    '''
    Create a function called patient_risk_score that takes a Hospital object and patient_id. Calculate risk score using formula: (patient.age / 100 * 30) + (patient.get_total_conditions() * 5 * 25/100) + (patient.get_average_severity() * 10 * 25/100) + (20 if recent records have abnormal vitals else 0). Use hospital.get_patient(patient_id) and hospital.get_recent_records(patient_id, 90). Returns: float between 0.0 and 100.0.
    '''
    patient = hospital.get_patient(patient_id)
    risk = (patient.age / 100 * 30) \
         + (patient.get_total_conditions() * 5 * 0.25) \
         + (patient.get_average_severity() * 10 * 0.25)

    recent_records = hospital.get_recent_records(patient_id, 90)
    abnormal = any(r.get('abnormal', False) for r in recent_records)
    if abnormal:
        risk += 20
    # Bound between 0 and 100
    return min(max(risk, 0.0), 100.0)

