import csv
import os
import json
import inspect

def _load_movies():
    # Load (demo assumes movie.csv is in same directory)
    movies = []
    csv_path = os.path.join(os.path.dirname(__file__), 'movie.csv')
    with open(csv_path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            # Clean up genres: split by '|' into a list
            row['genres'] = row['genres'].split('|') if row['genres'] else []
            movies.append(row)
    return movies

def _as_titles(movies):
    return [m['title'] for m in movies]

def _as_dicts(movies):
    # movieId as int, genres as list of strings, all fields
    out = []
    for m in movies:
        out.append({
            'movieId': int(m['movieId']),
            'title': m['title'],
            'genres': m['genres'],
        })
    return out

def _as_json_ld(movies):
    # As JSON-LD (per schema.org/Movie)
    out = []
    for m in movies:
        obj = {
            "@context": "https://schema.org",
            "@type": "Movie",
            "name": m['title'],
            "genre": m['genres'],
            "identifier": int(m['movieId']),
        }
        out.append(obj)
    return out

def movie_api():
    '''
    Create a movie_api function that automatically detects and switches between three different return formats (v1/v2/v3) based on the caller's context using movie.csv.
    v1: list of titles
    v2: list of dicts (movieId, title, genres)
    v3: list of JSON-LD dicts (schema.org/Movie)
    The function inspects the call stack and chooses the format based on the caller function's name.
    '''
    # Step 1: Load data from CSV
    movies = _load_movies()

    # Step 2: Inspect the call stack for clues
    stack = inspect.stack()
    # Search up the stack for function names indicating version
    v_tag = None
    for frame in stack:
        fname = frame.function.lower()
        if 'v1' in fname:
            v_tag = 'v1'
            break
        if 'v2' in fname:
            v_tag = 'v2'
            break
        if 'v3' in fname or 'jsonld' in fname or 'json_ld' in fname:
            v_tag = 'v3'
            break
    # Step 3: Select format
    if v_tag == 'v1':
        return _as_titles(movies)
    elif v_tag == 'v3':
        return _as_json_ld(movies)
    else:
        # default or v2
        return _as_dicts(movies)

