        for row in reader:
            # Convert overall_rating to float
            row['overall_rating'] = float(row['overall_rating'])
            # keep technical_score, communication_score, etc as is (string), or convert to int if detailed desired
            data.append(row)

    if report_type == 'summary':
        if not employee_id:
            raise ValueError("employee_id is required for summary report")
        # Find row with given employee_id
        for row in data:
            if row['employee_id'] == employee_id:
                return {
                    'employee_id': row['employee_id'],
                    'overall_rating': row['overall_rating'],
                    'goals_status': row['goals_status']
                }
